import math

def wilson_lower(correct, n, z=1.96):
    if n == 0:
        return 0.0
    p = correct / n
    centre = p + z * z / (2 * n)
    spread = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))
    return (centre - spread) / (1 + z * z / n)

def run_eval(tools, cases, model):
    correct, toks = 0, []
    for c in cases:
        resp = llm.complete(model=model, messages=[{'role': 'user', 'content': c.prompt}],
                            tools=[t.as_llm_tool() for t in tools], temperature=0)
        call = resp.tool_calls[0] if resp.tool_calls else None
        ok = call is not None and call.name == c.expected_tool
        # tricky part: score arguments too, subset match on the expected keys
        if ok and c.expected_args:
            ok = all(call.args.get(k) == v for k, v in c.expected_args.items())
        correct += ok
        if call is not None and ok:
            toks.append(count_tokens(json.dumps(execute_stub(call))))
    n = len(cases)
    return EvalReport(correct / n, wilson_lower(correct, n),
                      sum(toks) / max(len(toks), 1), version_of(tools))

def gate(report):
    return report.lower_bound >= 0.90 and report.avg_reply_tokens <= 1500

