import posixpath

def read_path(ctx, path):
    norm = posixpath.normpath("/" + path)
    if ".." in path or not norm.startswith("/brain/"):
        raise NotFound(path)
    topic, entry = parse(norm)                          # resolves only against the catalog
    ids = catalog.ids(ctx.tenant, topic) & acl.visible(ctx)
    return render(topic, entry, ids)
